def round_half_to_even(n: float) -> int:
    """Rounds a given floating-point number to the nearest integer, rounding half to even as per the IEEE 754 standard.

    Args:
        n (float): The floating-point number to be rounded.

    Returns:
        int: The rounded integer.
    """
    # Extract the fractional part of the number
    fractional_part = n % 1

    # Handle positive and negative numbers separately
    if n >= 0:
        if fractional_part > 0.5 or (fractional_part == 0.5 and int(n) % 2 == 0):
            return int(n + 0.5)
        else:
            return int(n)
    else:
        if fractional_part < -0.5 or (fractional_part == -0.5 and int(n) % 2 != 0):
            return int(n - 0.5)
        else:
            return int(n)

