from typing import List, Dict

def _dictsum(dicts: List[Dict[str, int]]) -> Dict[str, int]:
    """
    Sum the values of the same keys across multiple dictionaries.

    Args:
        dicts (List[Dict[str, int]]): A list of dictionaries with string keys and integer values.

    Returns:
        Dict[str, int]: A dictionary with summed values for each key.
    """
    result = {}
    for dictionary in dicts:
        for key, value in dictionary.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

# Example usage
if __name__ == "__main__":
    dict_list = [
        {"a": 1, "b": 2},
        {"b": 3, "c": 4},
        {"a": 5, "d": 6}
    ]
    print(_dictsum(dict_list))  # Expected output: {'a': 6, 'b': 5, 'c': 4, 'd': 6}

